    projectRoot: root,
    storyId: STORY_ID,
    corpus: buildCorpusIndex(root),
    seeds: buildKeywordSeeds(routingInput),
    protectedSources: routingInput.protectedSources,
    mode,
    storyInputDigest: digestCandidateRoutingValue(routingInput),
    ...routingSnapshot,
  }));
